from __future__ import annotations

from typing import Literal

import httpx2
from pydantic_ai import ModelRetry, Tool, ToolFailed
from pydantic_ai.capabilities import Capability

from ds.ai.smashdb import _char_df
from ds.data import CHAR_GROUPS, CharGroup
from ds.data.raw.smashtube import MAX_SEARCH_TERM_CHARS, REGIONS, MatchVideos, Region, search_videos

__all__ = ["find_match_videos", "smashtube_capability"]

_INSTRUCTIONS = """\
To find match videos (VODs) of competitive Smash Ultimate, use find_match_videos. It searches
smash-tube.com, an index of YouTube match videos, by player tags, characters, free text and region.
- Every filter is optional but give at least one. Combine them to narrow down, eg player_1 +
  char_2 for "Sparg0 against Little Mac", or char_1 + char_2 for a character matchup.
- player_1 / player_2 are player TAGS (people: 'Sparg0', 'acola'). Characters ('Joker', 'Little
  Mac', 'Cloud') go in char_1 / char_2: "Joker vs Little Mac videos" is char_1='joker',
  char_2='little_mac'.
- A name that could be either is treated as the character: the tool moves a player field that is
  exactly a character's name into a character field. The result's `query` shows what was really
  searched; if it differs from what you passed, tell the user (eg "searched Joker as the
  character"). Pass players_are_tags=true only when the user says it is a person's tag.
- Results come 10 per page, newest first; `total` is the site's count ('500+' = more than 500) and
  `pages` how many pages exist. Ask for another `page` only when the user wants more.
- The user's app shows the returned videos as a playable gallery, so don't repeat the whole list:
  say what was searched and how many were found, and point out a few videos by title and date.
  When you do name a video, link it with its `url`.
- Which characters appear is only in each video's `title`, written however the uploader did. Don't
  claim a video has a character unless the title says so.
- No results usually means a misspelt tag or too many filters: retry with fewer filters before
  telling the user nothing exists."""


def _character_named(text: str) -> str:
    """The char id when text is exactly a character's id or name (any case), else ''."""
    wanted = text.strip().lower()
    if not wanted:
        return ""
    chars = _char_df()
    for char_id, name in zip(chars["id"], chars["name"], strict=True):
        if wanted in (char_id.lower(), name.lower()) or wanted.replace(" ", "_") == char_id.lower():
            return char_id
    return ""


def _players_to_characters(players: list[str], chars: list[str]) -> tuple[list[str], list[str]]:
    """Move player tags that are character names into free character slots.

    "Joker" could be a player's tag or the character; the character is the better default.
    Each such tag goes to its own side's character slot, else the other side's; with both
    slots taken it stays a player tag (two characters are already given, so it is a person).
    """
    players, chars = list(players), list(chars)
    for i, tag in enumerate(players):
        char_id = _character_named(tag)
        if not char_id:
            continue
        if char_id in chars:  # the same character given twice: drop the player copy
            players[i] = ""
            continue
        slot = next((j for j in (i, 1 - i) if not chars[j]), None)
        if slot is not None:
            chars[slot], players[i] = char_id, ""
    return players, chars


def _site_char_id(char: CharGroup | str | None) -> str:
    """The char id smash-tube is searched with for a pick ('' for none). The site has one entry
    per character-select pick (Pokemon Trainer, Pyra/Mythra), so a group's first fighter
    stands for it. Text (a direct Python call) is parsed like the model's arguments.
    """
    if char is None or (isinstance(char, str) and not char.strip()):
        return ""
    try:
        group = CharGroup(char.strip() if isinstance(char, str) else char)
    except ValueError as e:
        raise ModelRetry(f"No character matches {char!r}. Use find_character to look up valid ids.") from e
    return CHAR_GROUPS.get(group.value, (group.value,))[0]


def find_match_videos(
    player_1: str = "",
    player_2: str = "",
    # a character type: validated, listed in the schema, the choice input (one pick) in the
    # app's form (tool_forms: any CharEnum parameter gets one); like get_player_usage's
    # vs_characters
    char_1: CharGroup | None = None,
    char_2: CharGroup | None = None,
    search_term: str = "",
    # choices in the type, so the tool's schema lists them (for the model and for forms)
    region: Region | Literal[""] = "",
    page: int = 1,
    players_are_tags: bool = False,
) -> MatchVideos:
    """Search smash-tube.com for Smash Ultimate match videos on YouTube (at least one filter).

    Args:
        player_1: a player's tag (a person, not a character), eg 'Sparg0'.
        player_2: the opponent's tag (a person, not a character), eg 'acola'.
        char_1: a character in the match, eg 'little_mac' (a name like 'Little Mac' works too);
            'pokemon_trainer' / 'pyra_mythra' for those picks. Leave unset for any.
        char_2: the other character, eg 'cloud'.
        search_term: free text to match, eg an event name like 'Kagaribi' (20 characters
            at most).
        region: 'Japan', 'NA', 'EU' or 'Other'; leave empty for all regions.
        page: result page, from 1 (10 videos per page).
        players_are_tags: a player_1 / player_2 that is a character's name (eg 'Joker') is
            searched as that character by default. Set true only when the user says it is a
            person's tag.
    """
    if region and region not in REGIONS:
        by_lower = {r.lower(): r for r in REGIONS}
        if region.lower() not in by_lower:
            raise ModelRetry(f"region must be one of {list(REGIONS)} or empty, got {region!r}.")
        region = by_lower[region.lower()]
    if len(search_term.strip()) > MAX_SEARCH_TERM_CHARS:
        raise ModelRetry(f"search_term is limited to {MAX_SEARCH_TERM_CHARS} characters; use a shorter phrase.")
    chars = [_site_char_id(char) for char in (char_1, char_2)]
    players = [player_1.strip(), player_2.strip()]
    if not players_are_tags:
        players, chars = _players_to_characters(players, chars)
    try:
        return search_videos(
            player_1=players[0],
            player_2=players[1],
            char_1=chars[0],
            char_2=chars[1],
            search_term=search_term,
            region=region,
            page=page,
        )
    except ValueError as e:  # no filter given, bad page, page layout changed
        raise ModelRetry(f"{e}.") from e
    except httpx2.HTTPStatusError as e:
        # final, not a retry: a second failed call would end the whole run with an error
        raise ToolFailed(f"smash-tube.com returned {e.response.status_code}; tell the user the search failed.") from e


smashtube_capability = Capability(
    id="smashtube",
    description="smash-tube.com match videos (YouTube VODs) by player, character, event text and region.",
    instructions=_INSTRUCTIONS,
    # fixed-shape result -> pydantic model (see .agents/instructions/pkgs.md, pydantic-ai)
    tools=[Tool(find_match_videos, include_return_schema=True)],
    # deferred: instructions + tool def only enter context once a video question comes up
    defer_loading=True,
)
